<?php require __DIR__.'/app.php';require __DIR__.'/header.php';$items=entries($kind);?><section class="section"><div class="container"><h1><?=e($title)?></h1><?php if(!$items):?><p>Please contact us for information about <?=e(strtolower($title))?>.</p><?php endif;?><div class="row entry-grid"><?php foreach($items as $item):?><div class="col-md-6"><article class="company-card"><?php if($img=imagepath($item['image'])):?><img src="<?=e($img)?>" alt="<?=e($item['title'])?>"><?php endif;?><h2><?=e($item['title'])?></h2><p><?=e($item['summary'])?></p><?php if($detail):?><a href="<?=e($detail)?>.php?id=<?=$item['id']?>">Read more →</a><?php else:?><p class="body-copy"><?=e($item['body'])?></p><?php endif;?></article></div><?php endforeach;?></div></div></section><?php require __DIR__.'/footer.php';?>